node --input-type=module <<'JS' > /private/tmp/willyou-m9-u03-20261018-matrix.json
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { platform, arch, release } from 'node:os';
import { scoreFileName, FILE_FUZZY_REVISION } from './src/renderer/features/files/file-fuzzy-model.mjs';
const expected = [['foo', 110037], ['foo.ts', 110024], ['Foo.ts', 110004]];
const rows = ['foo', 'FOO'].flatMap(query => expected.map(([name, expectedScore]) => {
  const result = scoreFileName(query, name);
  assert.equal(result.score, expectedScore);
  assert.equal(result.matched, true);
  return { query, name, expectedScore, actualScore: result.score, matched: result.matched, status: 'passed' };
}));
for (const [name] of expected) assert.deepEqual(scoreFileName('foo', name), scoreFileName('FOO', name));
console.log(JSON.stringify({ recordedAt: new Date().toISOString(), platform: platform(), architecture: arch(), osRelease: release(), nodeVersion: process.version, moduleRevision: FILE_FUZZY_REVISION, productionSha256: createHash('sha256').update(readFileSync('src/renderer/features/files/file-fuzzy-model.mjs')).digest('hex'), rows, asciiQueryCaseEquivalent: true, passed: rows.length }, null, 2));
